import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 10 话 文本截断：给不守规矩的文字收口","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.10-text-truncation.md","filePath":"comics/css/EP.10-text-truncation.md","lastUpdated":1793421609000}'),l={name:"comics/css/EP.10-text-truncation.md"};function n(r,e,c,d,s,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-10-话-文本截断-给不守规矩的文字收口" tabindex="-1">漫画 · 第 10 话 文本截断：给不守规矩的文字收口 <a class="header-anchor" href="#漫画-·-第-10-话-文本截断-给不守规矩的文字收口" aria-label="Permalink to &quot;漫画 · 第 10 话 文本截断：给不守规矩的文字收口&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/10-text-truncation">docs/css/10-text-truncation.md</a> ｜ 原画：<a href="./EP.10-text-truncation.svg">EP.10-text-truncation.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。文件列表里一个超长文件名把&quot;下载&quot;按钮顶出了屏幕，省略号三件套写齐也不出现，一度怀疑浏览器针对她。</li><li><strong>标签君</strong>：HTML5 结构师，掏出 min-content 原理图说明 flex 子项为什么&quot;拒绝收缩&quot;，并演示多行省略与长词断行的分工。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>文本是界面里最不守规矩的内容：设计稿永远是短标题，真实数据永远超长。像素酱按教程写了 <code>text-overflow: ellipsis</code> 却毫无效果，最后发现问题不在属性，而在布局——盒子根本没被压缩。本话讲清省略号出现的必要条件、flex/grid 的 min-content 下限、多行截断四件套，以及长 URL 该在哪里断行。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>.title { flex: 1 }</code> 的弹性项里塞了一个超长文件名，右侧按钮被直接顶出容器。根因是 flex 子项的 <code>min-width</code> 默认值为 <code>auto</code>，计算为 <strong>min-content</strong>——&quot;缩到不能再缩的宽度&quot;，对英文/URL 来说等于最长单词的宽度。弹性算法不敢压缩它，于是内容溢出，省略号永远没有出场机会。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>单行省略必须同时凑齐三件事：<code>white-space: nowrap</code>（禁止换行，文本才有机会&quot;超出&quot;）、<code>overflow: hidden</code>（超出被裁，省略号才有地方画）、<code>text-overflow: ellipsis</code>（在裁剪边界渲染 …）。而 flex 行里还要补第四行：<code>min-width: 0</code> 显式解除 min-content 下限，盒子被真正压窄后，三件套才在收缩后的宽度上生效。grid 轨道对应的写法是 <code>minmax(0, 1fr)</code>，列方向 flex 则用 <code>min-height: 0</code>。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>商品流卡片要求等高：标题无论 5 个字还是 50 个字都占 2 行，靠 <code>-webkit-box + box-orient:vertical + line-clamp:2 + overflow:hidden</code> 四件套，标准属性 <code>line-clamp: 2</code> 双写兜底。长 URL 断行注意区分：<code>overflow-wrap: anywhere</code> 的断行点<strong>计入 min-content</strong>，能让 flex 项真正缩窄；<code>break-word</code> 视觉上也断，但最小宽度不变，救不了 flex 溢出。<code>word-break: break-all</code> 切得最碎，只留给 URL、哈希、代码这类不可读字符串。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>单行三件套：nowrap + overflow:hidden + ellipsis，少一个省略号都不出现。</li><li>flex/grid 子项先写 <code>min-width:0</code>（或 <code>minmax(0,1fr)</code>），盒子被压窄才谈截断。</li><li>多行 line-clamp 四件套与标准属性双写；URL 用 anywhere，break-all 只给代码。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：flex 行里标题写了 <code>flex:1</code> + 省略三件套，省略号还是不出现，按钮依旧被顶飞，为什么？一行修复是什么？</p><p><strong>答</strong>：flex 子项 <code>min-width</code> 默认是 <code>auto</code>（= min-content），长文件名让它的最小宽度等于最长单词，弹性算法拒绝把它压到更窄，内容没有溢出到&quot;被裁剪&quot;的状态，三件套自然无效。修复：给标题加 <code>min-width: 0</code>（grid 用 <code>minmax(0,1fr)</code>，列方向用 <code>min-height:0</code>）。排查顺序：nowrap → overflow:hidden → ellipsis → 宽度确定 → min-width:0，90% 的问题在这五步内。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>单行省略多场景实验台（普通块/flex/grid/table/button + min-width:0 修复开关）：<a href="./../../examples/css/10-text-truncation/index-01-single-line.html">examples/css/10-text-truncation/index-01-single-line.html</a></li><li>1~5 行 line-clamp 滑块实验台（缺属性对照）：<a href="./../../examples/css/10-text-truncation/index-02-multi-line.html">index-02-multi-line.html</a></li><li>长 URL / 长英文 / 中英混排断行对照墙：<a href="./../../examples/css/10-text-truncation/index-03-word-breaking.html">index-03-word-breaking.html</a></li><li>综合实战：电商卡片 + 省略表格 + 文件名中段截断 + 智能 tooltip：<a href="./../../examples/css/10-text-truncation/index-04-real-layout.html">index-04-real-layout.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 11 话《CSS 进阶技巧》——CSS 篇收官：aspect-ratio、object-fit、sticky、scroll-snap、clip-path 一箱散装高频军火。</p>',22)])])}const x=t(l,[["render",n]]);export{u as __pageData,x as default};
